                post_hook={
                    "sql": "create or replace table snitch_db.maplemonk.cogs_otb as with a as ( SELECT CASE WHEN subvention IS NULL OR subvention = \'\' THEN NULL ELSE REGEXP_REPLACE( REGEXP_REPLACE( REGEXP_REPLACE( REGEXP_REPLACE( TRIM(subvention), \'\\s+\', \'\' ), \'^R4\', \'4\' ), \'/.*\', \'\' ), \'^([^-]+-[^-]+).*\', \'\\1\' ) END AS normalized_sku, Proj_qty, SKU_STATUS_, expected_delivery_date, revised_delivery_date, ifnull(revised_delivery_date, expected_delivery_date) FDD, category, lower( CASE WHEN CATEGORY IS NULL OR TRIM(CATEGORY) = \'\' THEN NULL -- Most specific first WHEN LOWER(CATEGORY) LIKE \'%trackpants%\' THEN \'Trackpants\' WHEN LOWER(CATEGORY) LIKE \'%sweatshirt%\' THEN \'Sweatshirt\' WHEN REGEXP_LIKE(LOWER(CATEGORY), \'.*t[-_ ]?shirt.*|.*tee.*\') THEN \'Tshirts\' WHEN LOWER(CATEGORY) LIKE \'%overshirt%\' THEN \'Overshirt\' -- Bottomwear WHEN LOWER(CATEGORY) LIKE \'%cargo%\' THEN \'Cargo\' WHEN LOWER(CATEGORY) LIKE \'%jogger%\' THEN \'Joggers\' WHEN LOWER(CATEGORY) LIKE \'%trouser%\' OR LOWER(CATEGORY) LIKE \'%pant%\' THEN \'Trousers\' WHEN LOWER(CATEGORY) LIKE \'%chino%\' THEN \'Chino\' WHEN LOWER(CATEGORY) LIKE \'%short%\' THEN \'Shorts\' WHEN LOWER(CATEGORY) LIKE \'%pyjama%\' OR LOWER(CATEGORY) LIKE \'%pj%\' THEN \'Pyjamas\' -- Denim / jeans WHEN LOWER(CATEGORY) LIKE \'%denim%\' THEN \'Denim\' WHEN LOWER(CATEGORY) LIKE \'%jean%\' THEN \'Jeans\' -- Topwear / outerwear WHEN LOWER(CATEGORY) LIKE \'%hoodie%\' THEN \'Hoodies\' WHEN LOWER(CATEGORY) LIKE \'%sweater%\' THEN \'Sweater\' WHEN LOWER(CATEGORY) LIKE \'%shirt%\' THEN \'Shirts\' WHEN LOWER(CATEGORY) LIKE \'%jacket%\' THEN \'Jackets\' WHEN LOWER(CATEGORY) LIKE \'%blazer%\' THEN \'Blazer\' -- Sets WHEN REGEXP_LIKE(LOWER(CATEGORY), \'.*coord.*|.*co-ord.*\') THEN \'Coords\' -- Innerwear WHEN LOWER(CATEGORY) LIKE \'%boxer%\' THEN \'Boxers\' WHEN LOWER(CATEGORY) LIKE \'%innerwear%\' OR LOWER(CATEGORY) LIKE \'%vest%\' OR LOWER(CATEGORY) LIKE \'%brief%\' THEN \'Innerwear\' -- Footwear & accessories WHEN LOWER(CATEGORY) LIKE \'%shoe%\' OR LOWER(CATEGORY) LIKE \'%sneaker%\' OR LOWER(CATEGORY) LIKE \'%slipper%\' THEN \'Shoes\' WHEN LOWER(CATEGORY) LIKE \'%sunglass%\' THEN \'Sunglasses\' WHEN LOWER(CATEGORY) LIKE \'%belt%\' THEN \'Belts\' WHEN LOWER(CATEGORY) LIKE \'%bag%\' THEN \'Bags\' WHEN LOWER(CATEGORY) LIKE \'%accessor%\' THEN \'Accessories\' WHEN LOWER(CATEGORY) LIKE \'%perfume%\' OR LOWER(CATEGORY) LIKE \'%fragrance%\' THEN \'Perfumes\' ELSE category END ) AS cleaned_category FROM snitch_db.maplemonk.gs_product_tracking_new_main WHERE sku_status_ not in (\'Delivered\', \'Cancel\', \'Hold\') ), b as ( select sku, online_qty, expected_delivery_date FDD, lower(replace(Description, \'-\', \'\')) category from snitch_db.maplemonk.gs_onlinegoods_rts where ( TO_DATE(expected_delivery_date, \'DD/MM/YYYY\') > CURRENT_DATE() -4 or expected_delivery_date is null ) ), sold as ( select Distinct SKU_Group from snitch_db.maplemonk.category_journey where sku_group like \'4%\' ), c as ( select sku, qty, ifnull(FDD, \'No Date mentioned\') FDD, category, status from ( select normalized_sku sku, Proj_qty qty, FDD, cleaned_category category, sku_status_ status from a where normalized_sku not in ( select sku from b where sku not in ( select SKU_Group from sold ) ) union all select sku, online_qty qty, FDD, category, \'RTS\' status from b ) ), COGS AS ( SELECT sku_group, MAX(cp) AS cost_price FROM ( SELECT DISTINCT sku_group, cp FROM snitch_db.maplemonk.PURCHASE_ORDER_JOURNEY WHERE NULLIF(sku_group, \'\') IS NOT NULL UNION ALL SELECT CONCAT( SPLIT_PART(sku, \'-\', 1), \'-\', SPLIT_PART(sku, \'-\', 2) ) AS sku_group, MAX(cost_price) AS cp FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ) AS combined_data GROUP BY sku_group ), d as ( SELECT sku, FDD, Qty, c.status, lower(replace(ifnull(c.category, b.category), \'-\', \'\')) Category, print_design_mapped, CASE WHEN s.sku_group IS NOT NULL THEN \'Repeat\' ELSE \'New\' END AS Remarks, cost_price COGS from c left join snitch_db.maplemonk.metafields_data b on c.sku = b.sku_group left join cogs on c.sku = cogs.sku_group LEFT JOIN sold s ON c.sku = s.sku_group ), e as ( select category, round(avg(cogs), 0) avg_cogs from d where cogs is not null group by 1 ), inwards_expected as ( select sku, FDD, qty, status, d.category, remarks, ifnull(cogs, avg_cogs) cogs_final, ifnull(cogs, avg_cogs) * qty COGS_value,CASE WHEN FDD = \'No Date mentioned\' THEN \'No Date mentioned\' when FDD is not null then TO_VARCHAR( DATE_TRUNC( \'MONTH\', TRY_TO_DATE(FDD, \'DD/MM/YYYY\') ), \'YYYY-MM\' ) ELSE \'Other\' END AS FDD_MONTH, CASE WHEN LOWER(sku) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(sku) LIKE \'r4mbg%\' THEN \'plus_size\' -- WHEN LOWER(b.style) LIKE \'%luxe%\' THEN \'luxe\' -- WHEN LOWER(b.style) LIKE \'%core%\' THEN \'core\' -- WHEN LOWER(b.category) IN (\'perfumes\',\'accessories\',\'bags\',\'belts\',\'sunglasses\',\'shoes\',\'slip-ons\') THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(sku) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(sku) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(sku) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(sku) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end L1_Category from d left join e on d.category = e.category ), f as ( select sku, L1_Category, category, FDD_month, COGS_value, qty from inwards_expected ), putaway_report as ( SELECT upper( trim( REVERSE( SUBSTRING( REVERSE(\"Item Type skuCode\"), CHARINDEX(\'-\', REVERSE(\"Item Type skuCode\")) + 1, LEN(\"Item Type skuCode\") ) ) ) ) AS SKU_group, TO_VARCHAR( DATE_TRUNC(\'MONTH\', \"PUTAWAY_UPDATED\"::DATE), \'YYYY-MM\' ) AS Month, SUM(\"PUTAWAY_COMPLETED_QUANTITY\") AS Qty FROM snitch_db.maplemonk.putaway_tracking WHERE \"PUTAWAY_UPDATED\" >= DATE \'2025-11-01\' AND LOWER(FINAL_TYPE) = \'new inward\' GROUP BY 1, 2 ), inwarded as ( select ff.SKU_group,CASE WHEN LOWER(ff.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(ff.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end L1_Category, lower( replace( ifnull( a.category,case WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' when upper(ff.sku_group) like \'4MSN%\' THEN \'Shirts\' when upper(ff.sku_group) like \'4MCR1004%\' then \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MCSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MTR0123%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSWHC%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWC%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MSKC%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MCRD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MCRT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MTLX%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MLRT%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(ff.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSW%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(ff.sku_group) LIKE \'4MST%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(ff.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'Belts\' WHEN UPPER(ff.sku_group) LIKE \'4MLX%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MPL%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'Accessories\' end ), \'-\', \'\' ) ) Category, Month, Qty, Qty * cost_price inward_value from putaway_report ff left join cogs b on ff.sku_group = b.sku_group left join snitch_db.maplemonk.metafields_data a on ff.sku_group = a.sku_group ), inv as ( WITH warehouse AS ( SELECT \"FACILITY\", UPPER( TRIM( REGEXP_REPLACE(\"Item SkuCode\"::STRING, \'-[^-]+$\', \'\') ) ) AS sku_group, \"Category Name\", SUM(\"INVENTORY\") AS \"Available\", SUM(\"Inventory Blocked\") AS \"Blocked\", SUM(TRY_TO_NUMBER(\"Not Found\")) AS \"Not Found\", SUM(\"Putaway Pending\") AS \"Putaway Pending\", SUM(\"Putback Pending\") AS \"Putback Pending\", SUM(\"Bad Inventory\") AS \"Bad Inventory\", SUM(\"Inventory Not Synced\") AS \"Not Synced\", SUM(\"Stock In Transfer\") AS \"Stock Transfer\" FROM snitch_db.maplemonk.snitch_final_inventory_wh2 WHERE \"FACILITY\" IN ( \'SAPL_EMIZA\', \'SAPL-WH1\', \'SAPL-WH2\', \'SAPL-NORTH-TAURU\' ) AND \"DATE\" = CAST(DATEADD(HOUR, 7, CURRENT_TIMESTAMP()) AS DATE) GROUP BY \"FACILITY\", UPPER( TRIM( REGEXP_REPLACE(\"Item SkuCode\"::STRING, \'-[^-]+$\', \'\') ) ), \"Category Name\" ), -- Offline/JIT quantities by sku_group offline_inv AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, SUM(inventory) AS available_inv, SUM(jit_qty) AS jit_inv FROM snitch_db.maplemonk.offline_master GROUP BY 1 ), -- Cost per sku_group COGS AS ( SELECT sku_group, MAX(cp) AS cost_price FROM ( SELECT DISTINCT sku_group, cp FROM snitch_db.maplemonk.PURCHASE_ORDER_JOURNEY WHERE NULLIF(sku_group, \'\') IS NOT NULL UNION ALL SELECT CONCAT( SPLIT_PART(sku, \'-\', 1), \'-\', SPLIT_PART(sku, \'-\', 2) ) AS sku_group, MAX(cost_price) AS cp FROM snitch_db.maplemonk.UC_FINAL_ITEM_MASTER GROUP BY 1 ) AS combined_data GROUP BY sku_group ), -- Optional mapping to get a canonical category per sku_group (from WH data) sku_group_category AS ( SELECT sku_group, MAX(\"Category Name\") AS category_name FROM warehouse GROUP BY 1 ), -- Warehouse rollup by sku_group (qty + COGS per bucket) wh_rollup_sku AS ( SELECT a.sku_group, MAX(a.\"Category Name\") AS category_name, -- Quantities SUM(a.\"Available\") AS qty_available, SUM(a.\"Blocked\") AS qty_blocked, SUM(a.\"Not Found\") AS qty_not_found, SUM(a.\"Bad Inventory\") AS qty_bad_inventory, SUM(a.\"Not Synced\") AS qty_not_synced, SUM(a.\"Putaway Pending\") AS qty_putaway_pending, SUM(a.\"Putback Pending\") AS qty_putback_pending, SUM(a.\"Stock Transfer\") AS qty_stock_transfer, -- COGS per bucket SUM(a.\"Available\" * COALESCE(b.cost_price, 0)) AS available_cogs, SUM(a.\"Blocked\" * COALESCE(b.cost_price, 0)) AS blocked_cogs, SUM(a.\"Not Found\" * COALESCE(b.cost_price, 0)) AS not_found_cogs, SUM(a.\"Bad Inventory\" * COALESCE(b.cost_price, 0)) AS bad_inventory_cogs, SUM(a.\"Not Synced\" * COALESCE(b.cost_price, 0)) AS not_synced_cogs, SUM(a.\"Putaway Pending\" * COALESCE(b.cost_price, 0)) AS putaway_pending_cogs, SUM(a.\"Putback Pending\" * COALESCE(b.cost_price, 0)) AS putback_pending_cogs, SUM(a.\"Stock Transfer\" * COALESCE(b.cost_price, 0)) AS stock_transfer_cogs, -- Total COGS across all buckets SUM( ( a.\"Available\" + a.\"Blocked\" + a.\"Not Found\" + a.\"Bad Inventory\" + a.\"Not Synced\" + a.\"Putaway Pending\" + a.\"Putback Pending\" + a.\"Stock Transfer\" ) * COALESCE(b.cost_price, 0) ) AS total_cogs FROM warehouse a LEFT JOIN cogs b ON a.sku_group = b.sku_group GROUP BY a.sku_group ), -- Offline/JIT rollup by sku_group (qty + COGS) offline_rollup_sku AS ( SELECT oi.sku_group, SUM(oi.available_inv) AS qty_offline_available, SUM(oi.available_inv * COALESCE(c.cost_price, 0)) AS offline_available_cogs, SUM(oi.jit_inv) AS qty_jit, SUM(oi.jit_inv * COALESCE(c.cost_price, 0)) AS jit_cogs FROM offline_inv oi LEFT JOIN cogs c ON oi.sku_group = c.sku_group GROUP BY oi.sku_group ), -- MP metrics per sku_group mp AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(days_since_inward) AS days_since_inward, SUM(mp_quant30) AS mp_quant_30 FROM snitch_db.maplemonk.category_journey GROUP BY 1 ), ff as ( SELECT COALESCE(w.sku_group, o.sku_group) AS sku_group, -- Best-effort readable Category label (keeps your renaming rules) CASE WHEN COALESCE(w.category_name, sgc.category_name) IN (\'Sweater\') THEN \'Sweaters\' WHEN COALESCE(w.category_name, sgc.category_name) = \'Footwear\' THEN \'Shoes\' WHEN COALESCE(w.category_name, sgc.category_name) = \'JOGGERS\' THEN \'Joggers & Trackpants\' WHEN COALESCE(w.category_name, sgc.category_name) = \'Jacket\' THEN \'Jackets\' WHEN COALESCE(w.category_name, sgc.category_name) = \'Trouser\' THEN \'Trousers\' WHEN COALESCE(w.category_name, sgc.category_name) = \'PYJAMAS\' THEN \'Night Suit & Pyjamas\' ELSE COALESCE(w.category_name, sgc.category_name) END AS \"Category Name\", -- Warehouse quantities w.qty_available, w.qty_blocked, w.qty_not_found, w.qty_bad_inventory, w.qty_not_synced, w.qty_putaway_pending, w.qty_putback_pending, w.qty_stock_transfer, -- Warehouse COGS w.available_cogs, w.blocked_cogs, w.not_found_cogs, w.bad_inventory_cogs, w.not_synced_cogs, w.putaway_pending_cogs, w.putback_pending_cogs, w.stoc