' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(ff.sku_group) LIKE \'4MST%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(ff.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'Belts\' WHEN UPPER(ff.sku_group) LIKE \'4MLX%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MPL%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'Accessories\' end ), \'-\', \'\' ) ) Category, IFNULL( SUM( CASE WHEN DATEDIFF(day, order_date, CURRENT_DATE) <= 29 THEN suborder_quantity::INT ELSE 0 END ), 0 ) AS store_L30D, IFNULL( SUM( CASE WHEN order_date BETWEEN DATE_TRUNC(\'MONTH\', CURRENT_DATE) AND CURRENT_DATE THEN suborder_quantity::INT ELSE 0 END ), 0 ) AS store_MTD FROM snitch_db.maplemonk.STORE_fact_items_offline ff left join snitch_db.maplemonk.metafields_data a on ff.sku_group = a.sku_group GROUP BY 1, 2, 3 ) SELECT COALESCE(a.sku_group, b.sku_group) AS sku_group, COALESCE(a.L1_Category, b.L1_Category) AS L1_Category, COALESCE(a.category, b.category) AS category, IFNULL(a.Shopify_L30D, 0) AS Shopify_L30D, IFNULL(a.Shopify_MTD, 0) AS Shopify_MTD, IFNULL(a.MP_L30D, 0) AS MP_L30D, IFNULL(a.MP_MTD, 0) AS MP_MTD, IFNULL(b.store_L30D, 0) AS store_L30D, IFNULL(b.store_MTD, 0) AS store_MTD FROM Shopify_MP a FULL OUTER JOIN store b ON a.sku_group = b.sku_group ) -- select category,sum(Shopify_L30D+MP_L30D+store_L30D) value from sales group by 1; , sku_master AS ( SELECT DISTINCT SKU_group, L1_Category, case when sm.Category = \'shirt\' then \'shirts\' when sm.Category = \'sweater\' then \'sweaters\' when sm.Category = \'cargo\' then \'cargo pants\' when sm.Category = \'tshirt\' then \'tshirts\' when sm.Category = \'denim\' or sm.Category like \'chino%\' then \'jeans\' else sm.Category end category, FROM ( SELECT sku SKU_group, L1_Category, Category FROM inwards_expected UNION SELECT SKU_group, L1_Category, Category FROM inwarded UNION SELECT SKU_group, L1_Category, Category FROM sales UNION SELECT SKU_group, L1_Category, Category FROM inv ) sm ), base_sales AS ( -- Shopify + Marketplace SELECT date, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' when type = \'Store\' then \'Offline\' END AS channel, gross_sales::INT AS qty, gross_quantity::int * ifnull(cost_price, 500) cogs_value, FROM snitch_db.maplemonk.horizontal_sales_categories left join cogs using(sku_group) ), sku_cogs as ( select SKU_Group, category, l1_category, COALESCE( cost_price, /* 1️⃣ Category-level average COGS */ CASE WHEN category IS NOT NULL THEN AVG(cost_price) OVER (PARTITION BY category) END, /* 2️⃣ L1-category-level average fallback */ AVG(cost_price) OVER (PARTITION BY l1_category) ) cogs from sku_master left join cogs using(sku_group) ), sales_data as ( SELECT sku_cogs.category, sku_cogs.L1_Category, SUM( CASE WHEN date BETWEEN DATE_TRUNC(\'MONTH\', CURRENT_DATE) AND CURRENT_DATE THEN gross_quantity::int ELSE 0 END ) * 0.75 sales_mtd_qty, SUM( CASE WHEN date BETWEEN DATE_TRUNC(\'MONTH\', CURRENT_DATE) AND CURRENT_DATE THEN cogs * gross_quantity::int ELSE 0 END ) * 0.75 AS MTD_Sales, SUM( CASE WHEN date between current_date() - 30 and current_date() THEN cogs * gross_quantity::int ELSE 0 END ) * 0.75 AS L30D_Sales, SUM( CASE WHEN date between current_date() -30 and current_date() THEN gross_quantity::int ELSE 0 END ) * 0.75 AS L30D_Sales_qty, sum( CASE WHEN date between \'2025-12-01\' and \'2025-12-31\' THEN cogs * gross_quantity::int ELSE 0 END ) * 0.75 dec_Sales, sum( CASE WHEN date between \'2025-12-01\' and \'2025-12-31\' THEN gross_quantity::int ELSE 0 END ) * 0.75 dec_Sales_qty, FROM snitch_db.maplemonk.horizontal_sales_categories left join sku_cogs using(sku_group) GROUP BY 1, 2 ), sales_mix as ( WITH base_sales AS ( -- Shopify + Marketplace SELECT date, sku_group, CASE WHEN type = \'Shopify\' THEN \'Shopify\' WHEN type = \'Marketplace\' THEN \'Marketplace\' when type = \'Store\' then \'Offline\' END AS channel, gross_sales::INT * 0.75 AS qty, gross_quantity::int * cogs * 0.75 cogs_value, FROM snitch_db.maplemonk.horizontal_sales_categories left join sku_cogs using(sku_group) ), sku_monthly AS ( SELECT sku_group, SUM( CASE WHEN date between \'2025-12-01\' and \'2025-12-31\' THEN cogs_value ELSE 0 END ) AS Dec_25_Sales, SUM( CASE WHEN date between \'2024-12-01\' and \'2024-12-31\' THEN qty ELSE 0 END ) AS Dec_Sales, SUM( CASE WHEN date between \'2025-01-01\' and \'2025-01-31\' THEN qty ELSE 0 END ) AS Jan_Sales, SUM( CASE WHEN date between \'2025-02-01\' and \'2025-02-28\' THEN qty ELSE 0 END ) AS feb_Sales, SUM( CASE WHEN date between \'2025-03-01\' and \'2025-03-31\' THEN qty ELSE 0 END ) AS mar_Sales, SUM( CASE WHEN date between \'2025-04-01\' and \'2025-04-30\' THEN qty ELSE 0 END ) AS apr_Sales, SUM( CASE WHEN date between current_date() -30 and current_date() THEN qty ELSE 0 END ) AS L30D_Sales, FROM base_sales GROUP BY sku_group ), cte as ( select lower( replace( ifnull( a.category,case WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' when upper(ff.sku_group) like \'4MSN%\' THEN \'Shirts\' when upper(ff.sku_group) like \'4MCR1004%\' then \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MCSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'MP-ST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-OS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-CS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MTR0123%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'MP-SR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-QS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'MP-SC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'MP-SJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'Caps\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSWHC%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWC%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MSKC%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MCRD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'4MCRT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MTLX%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MLRT%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXT%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MLXD%\' THEN \'Jeans\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSS%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSR%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSO%\' THEN \'Cargo Pants\' WHEN UPPER(ff.sku_group) LIKE \'4MSC%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MSK%\' THEN \'Jackets\' WHEN UPPER(ff.sku_group) LIKE \'4MSD%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSH%\' THEN \'Shorts\' WHEN UPPER(ff.sku_group) LIKE \'4MSP%\' THEN \'Pyjamas\' WHEN UPPER(ff.sku_group) LIKE \'4MSWH%\' THEN \'Hoodies\' WHEN UPPER(ff.sku_group) LIKE \'4MSWS%\' THEN \'Sweatshirts\' WHEN UPPER(ff.sku_group) LIKE \'4MSW%\' THEN \'Sweaters\' WHEN UPPER(ff.sku_group) LIKE \'4MTP%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MSJ%\' THEN \'Joggers & Trackpants\' WHEN UPPER(ff.sku_group) LIKE \'4MBZ%\' THEN \'Blazers\' WHEN UPPER(ff.sku_group) LIKE \'4MST%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MOS%\' THEN \'Overshirt\' WHEN UPPER(ff.sku_group) LIKE \'4MKP%\' THEN \'Trousers\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'Belts\' WHEN UPPER(ff.sku_group) LIKE \'4MLX%\' THEN \'Shirts\' WHEN UPPER(ff.sku_group) LIKE \'4MPL%\' THEN \'T-Shirts\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'Sunglasses\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'Shoes\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'Accessories\' end ), \'-\', \'\' ) ) Category, CASE WHEN LOWER(ff.sku_group) LIKE \'4mbg%\' THEN \'plus_size\' WHEN LOWER(ff.sku_group) LIKE \'r4mbg%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4ML%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MTL%\' THEN \'luxe\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSS%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSR%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGSD%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'4MBGST%\' THEN \'plus_size\' WHEN UPPER(ff.sku_group) LIKE \'SH00%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBL%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MHT%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MCP%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MBD%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SN%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'SH%\' THEN \'long_tail\' WHEN UPPER(ff.sku_group) LIKE \'4MSFC%\' THEN \'long_tail\' else \'Snitch\' end L1_Category, -- ff.* -- sum(shopify_sales) shopify_sales, sum(mp_sales) mp_sales, sum(offline_sales) offline_sales, sum(Dec_Sales) * 0.75 Dec_Sales, sum(jan_sales) * 0.75 jan_sales, sum(feb_sales) * 0.75 feb_sales, sum(mar_sales) * 0.75 mar_sales, sum(L30D_Sales) * 0.75 L30D_Sales, sum(Dec_25_Sales) * 0.75 Dec_25_Sales, sum(apr_sales) * 0.75 apr_sales, sum(Dec_25_Sales) Dec_25_Sales_2, -- sum(jan_sales) / nullif(sum(Dec_Sales), 0) Jan_Factor, -- sum(feb_sales) / nullif(sum(Dec_Sales), 0) feb_Factor, -- sum(mar_sales) / nullif(sum(Dec_Sales), 0) mar_Factor from sku_monthly ff left join snitch_db.maplemonk.metafields_data a on ff.sku_group = a.sku_group group by 1, 2 order by 1 ) select L1_Category, category, concat(L1_Category, Category) con, Dec_25_Sales / 10000000, case when l1_category = \'long_tail\' then least( 1, ( sum(jan_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) ) else ( sum(jan_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) end jan_factor, case when l1_category = \'long_tail\' then least( 1, ( sum(feb_sales) over(partition by category) / nullif(sum(dec_Sales) over(partition by category), 0) ) ) else ( sum(feb_sales) over(partition by category) / nullif(sum(dec_Sales) over(partition by category), 0) ) end feb_factor, case when l1_category = \'long_tail\' or L1_Category = \'plus_size\' then least( 1, ( sum(mar_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) ) else ( sum(mar_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) end mar_factor, -- case -- when l1_category = \'long_tail\' -- or L1_Category = \'plus_size\' then least( -- 1, -- ( -- sum(apr_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) -- ) -- ) -- else ( -- sum(apr_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) -- ) -- end apr_factor, case when l1_category = \'long_tail\' then least( 1, sum(jan_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) else ( sum(jan_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) end * Dec_25_Sales jan_26_pred, case when l1_category = \'long_tail\' then least( 1, ( sum(feb_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) ) else ( sum(feb_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) end * Dec_25_Sales feb_26_pred, case when l1_category = \'long_tail\' or L1_Category = \'plus_size\' then least( 1, ( sum(mar_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) ) else ( sum(mar_sales) over(partition by category) / nullif(sum(Dec_Sales) over(partition by category), 0) ) end * Dec_25_Sales mar_26_pred, L30D_Sales / sum(L30D_Sales) over() Sales_mix, Dec_25_Sales_2 / 10000000, from cte ), sales_pred as ( select L1_Category, category, con, ifnull(inv_mix, 0) inv_mix, ifnull(Sales_mix, 0) Sales_mix, jan_factor, feb_factor, mar_factor, sum(jan_26_pred) over() * ( ifnull(inv_mix, 0) * 0.35 + ifnull(Sales_mix, 0) * 0.50 + ifnull( Jan_Factor / nullif(sum(Jan_Factor) over(), 0), 0 ) *.15 ) Jan_26_pred, sum(Feb_26_pred) over() *( ifnull(inv_mix, 0) * 0.35 + ifnull(Sales_mix, 0) * 0.5 + ifnull( feb_Factor / nullif(sum(feb_Factor) over(), 0), 0 ) *.15 ) Feb_26_pred, sum(Mar_26_pred) over() *( ifnull(inv_mix, 0) * 0.35 + ifnull(Sales_mix, 0) * 0.5 + ifnull( mar_Factor / nullif(sum(mar_Factor) over(), 0), 0 ) *.15 ) Mar_26_pred, from inv_mix a full outer join sales_mix b using(con, L1_Category, category) ), sales_pred_pivot as ( SELECT L1_Category, Category, month_col, CASE lower(month_col) WHEN \'jan_26_pred\' THEN \'2026-01\' WHEN \'feb_26_pred\' THEN \'2026-02\' WHEN \'mar_26_pred\' THEN \'2026-03\' END AS Month, round(pred_value / 10000000, 1) pred_value, Sales_mix, inv_mix FROM sales_pred UNPIVOT ( pred_value FOR month_col IN (Jan_26_pred, Feb_26_pred, Mar_26_pred) ) ), months AS ( SELECT TO_VARCHAR( DATEADD(month, seq4(), \'2025-11-01\'::date), \'YYYY-MM\' ) AS month FROM TABLE(GENERATOR(ROWCOUNT => 8)) ), sku_month AS ( SELECT distinct s.SKU_group, min(s.L1_Category) L1_Category, min(s.Category) Category, m.month FROM sku_master s CROSS JOIN months m group by 1, 4 ), final_report AS ( SELECT distinct sm.month, sm.SKU_group, sm.L1_Category, case when sm.Category = \'shirt\' then \'shirts\' when sm.Category = \'sweater\' then \'sweaters\' when sm.Category = \'cargo\' then \'cargo pants\' when sm.Category = \'tshirt\' then \'tshirts\' when sm.Category = \'denim\' or sm.Category like \'chino%\' then \'jeans\' else sm.Category end category, /* Inwards Expected */ IFNULL(ie.qty, 0) AS inward_expected_qty, IFNULL(ie.COGS_value, 0) AS inward_expected_cogs, /* Inwarded */ IFNULL(iw.qty, 0) AS inwarded_qty, IFNULL(iw.inward_value, 0) AS inwarded_cogs, /* Inventory — only current month */ CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.Total_cogs, 0) END AS inventory_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.putaway_pending_cogs, 0) END AS putaway_pending_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.putback_pending_cogs, 0) END AS putback_pending_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.qty_offline_available, 0) END AS qty_offline_available, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.offline_available_cogs, 0) END AS offline_available_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.qty_available, 0) END AS WH_available, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.WH_cogs, 0) END AS WH_cogs, CASE WHEN sm.month = TO_VARCHAR(DATE_TRUNC(\'MONTH\', CURRENT_DATE), \'YYYY-MM\') THEN IFNULL(inv.jit_cogs, 0) END AS jit_cogs FROM sku_month sm /* Inwards Expected */ LEFT JOIN ( select sku, fdd_month, sum(qty) qty, sum(COGS_value) COGS_value from inwards_expected group by 1, 2 ) ie ON ie.sku = sm.SKU_group AND ie.FDD_MONTH = sm.month /* Inwarded */ LEFT JOIN inwarded iw ON iw.SKU_group = sm.SKU_group AND iw.month = sm.month /* Sales (no month join) */ LEFT JOIN sales s ON s.SKU_group = sm.SKU_group /* Inventory snapshot (current only) */ LEFT JOIN inv ON inv.SKU_group = sm.SKU_group left join cogs on s.SKU_group = cogs.sku_group ), final_wait as ( select month, L1_Category, category, round( sum( ifnull(offline_available_cogs, 0) + ifnull(WH_cogs, 0) + ifnull(jit_cogs, 0) ) / 10000000, 5 ) opening_inventory_cogs, -- round(sum(ifnull(L30D_Sales,0)) / 10000000, 1) Sales_L30D_cogs, -- round(sum(ifnull(MTD_Sales,0)) / 10000000, 1) Sales_MTD_cogs, round(sum(inwarded_cogs) / 10000000, 1) Inwarded, round(sum(Inward_expected_cogs) / 10000000, 1) Inward_expected_cogs, round(sum(putaway_pending_cogs) / 10000000, 1) putaway_pending_cogs, round(sum(putback_pending_cogs) / 10000000, 1) putback_pending_cogs, sum(qty_offline_available) qty_offline_available, round(sum(offline_available_cogs) / 10000000, 5) offline_available_cogs, sum(WH_available) WH_available, round(sum(WH_cogs) / 10000000, 5) WH_cogs, round(sum(jit_cogs) / 10000000, 5) jit_cogs, from final_report -- where SKU_Group=\'4MST2189-02\' -- left join sales_data using(L1_Category,category) group by 1, 2, 3 order by 1, 2, 3 ) -- select * from final_wait where category=\'shirts\' and L1_Category=\'Snitch\'; , final_base as ( select L1_Category, category, Month, opening_inventory_cogs, -- Sales_MTD_cogs, Inwarded, pred_value, Inward_expected_cogs, round( case when TO_DATE(month || \'-01\', \'YYYY-MM-DD\') = DATE_TRUNC( \'MONTH\', current_date() ) then MTD_Sales end / 10000000, 1 ) Sales_MTD_cogs, round( case when TO_DATE(month || \'-01\', \'YYYY-MM-DD\') = DATE_TRUNC( \'MONTH\', current_date() ) then L30D_Sales end / 10000000, 1 ) Sales_L30D_cogs from final_wait left join sales_pred_pivot using(L1_Category, category, month) left join sales_data using(L1_Category, category) ), base_1 as ( SELECT a.L1_Category, a.category, TO_DATE(a.month || \'-01\', \'YYYY-MM-DD\') AS month_dt, case when opening_inventory_cogs=0 then null else opening_inventory_cogs end current_opening_cogs, COALESCE(inwarded_target_set::float, 0) - COALESCE(pred_value, 0) AS net_adj, opening_inventory_cogs, Sales_MTD_cogs, Inwarded, pred_value, inwarded_target_set::float INWARDED_TARGET_full_month, Inward_expected_cogs, Sales_L30D_cogs FROM final_base a left join snitch_db.maplemonk.inwards_target_sheet b on a.month = b.month and a.category = b.category and a.l1_category = b.l_1_category ), e_anchor AS ( SELECT *, LAST_VALUE(current_opening_cogs IGNORE NULLS) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED following ) AS base_current_opening_cogs FROM base_1 ), sales_temp as ( select TO_VARCHAR(date, \'YYYY-MM\') month, sku_cogs.L1_Category, sku_cogs.category, round( (sum(cogs * gross_quantity::int) * 0.75) / 10000000, 4 ) actual_sales from snitch_db.maplemonk.horizontal_sales_categories left join sku_cogs using(sku_group) where date between \'2025-12-01\' and \'2026-03-01\' group by 1, 2, 3 ), final_b as( SELECT a.L1_Category, a.category, TO_VARCHAR(month_dt, \'YYYY-MM\') AS month_dt, current_opening_cogs, current_opening_cogs * 30 / nullif(Sales_L30D_cogs, 0) Current_DOI, ifnull(base_current_opening_cogs,0) base_current_opening_cogs, opening_inventory_cogs, Sales_MTD_cogs, Inwarded, pred_value Sales_Pred, Inward_expected_cogs, Sales_L30D_cogs, INWARDED_TARGET_full_month, CASE WHEN month_dt < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN INWARDED_TARGET_full_month WHEN month_dt = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN INWARDED_TARGET_full_month * DAY(CURRENT_DATE()) / DAY(LAST_DAY(CURRENT_DATE())) ELSE 0 END AS Inward_TD_target, ifnull(actual_sales, 0) actual_sales, CASE /* Past months → nothing left */ WHEN a.month_dt < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN 0 /* Current month → prorated remaining including today */ WHEN a.month_dt = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN pred_value * ( ( DAY(LAST_DAY(CURRENT_DATE())) - DAY(CURRENT_DATE()) + 1 ) / DAY(LAST_DAY(CURRENT_DATE())) ) ELSE sales_pred END AS sales_left_to_do, FROM e_anchor a left join snitch_db.maplemonk.inwards_target_sheet b on TO_VARCHAR(month_dt, \'YYYY-MM\') = b.month and a.category = b.category and a.l1_category = b.l_1_category left join sales_temp c on TO_VARCHAR(month_dt, \'YYYY-MM\') = c.month and a.category = c.category and a.l1_category = c.l1_category where TO_VARCHAR(month_dt, \'YYYY-MM\') in (\'2026-01\', \'2026-02\', \'2026-03\') -- group by 1 ) , calc AS ( SELECT *, /* cumulative actuals till month */ TO_DATE(month_dt, \'YYYY-MM\') AS month_date, SUM(COALESCE(actual_sales, 0)) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS sales_done_till_now, SUM(COALESCE(inwarded, 0)) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW ) AS inwards_done_till_now, /* future projections */ SUM(COALESCE(sales_left_to_do, 0)) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ) AS sales_remaining, SUM(COALESCE(Inward_expected_cogs, 0)) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ) AS inwards_remaining, SUM(COALESCE(INWARDED_TARGET_full_month-ifnull(inwarded,0), 0)) OVER ( PARTITION BY L1_Category, category ORDER BY month_dt ROWS BETWEEN CURRENT ROW AND UNBOUNDED FOLLOWING ) AS inwards_remaining_2, FROM final_b ) SELECT L1_Category, category, month_dt, round(BASE_current_opening_cogs,2) BASE_current_opening_cogs, round(opening_inventory_cogs,2) AS current_inventory_cogs, round(opening_inventory_cogs * 30 / NULLIF(Sales_L30D_cogs, 0),2) AS Current_DOI, /* ================= OPENING CALCULATED ================= */ round(greatest( 0,CASE /* past & current */ WHEN month_date <= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs + sales_done_till_now - inwards_done_till_now /* future */ ELSE base_current_opening_cogs - ( SELECT SUM(b2.sales_left_to_do) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') < calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) + ( SELECT SUM(b2.Inward_expected_cogs) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') < calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) END ),2) AS opening, round(greatest( 0,CASE /* past & current */ WHEN month_date <= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs + sales_done_till_now - inwards_done_till_now /* future */ ELSE base_current_opening_cogs - ( SELECT SUM(b2.sales_left_to_do) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') < calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) + ( SELECT SUM(COALESCE(b2.INWARDED_TARGET_full_month-ifnull(b2.inwarded,0), 0)) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') < calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) END ),2) AS Opening_target, Sales_Pred, round(avg_cogs,2) Avg_cogs, round(COALESCE(sales_left_to_do, 0),2) sales_pred_left_to_do, round(actual_sales,2)actual_sales, round(inwarded,2)inwarded, round((inwarded*10000000)/avg_cogs,0) inwarded_qty, INWARDED_TARGET_full_month, round((INWARDED_TARGET_full_month*10000000)/avg_cogs,0) Inward_Target_Full_month_Qty, round(Inward_TD_target,2) Inward_TD_target, round((Inward_TD_target*10000000)/avg_cogs,0) Inward_Target_TD_Qty, round(inwarded - Inward_TD_target,2) AS delta_TD, round(((inwarded - Inward_TD_target)*10000000)/avg_cogs,0) delta_TD_Qty, round(inwarded - INWARDED_TARGET_full_month,2) AS delta_full_month, round(((inwarded - INWARDED_TARGET_full_month)*10000000)/avg_cogs,0) delta_Full_month_Qty, round(Inward_expected_cogs,2) Inward_expected_cogs, /* ================= CLOSING CALCULATED ================= */ round(greatest( 0,CASE /* past */ WHEN month_date < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs + ( SELECT SUM(b2.actual_sales) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) - ( SELECT SUM(b2.inwarded) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) /* current */ WHEN month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs - sales_left_to_do + Inward_expected_cogs /* future */ ELSE base_current_opening_cogs - ( SELECT SUM(b2.sales_left_to_do) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) + ( SELECT SUM(b2.Inward_expected_cogs) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) END ),2) AS closing, -- CLosing DOI round(greatest( 0,CASE /* past */ WHEN month_date < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs + ( SELECT SUM(b2.actual_sales) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) - ( SELECT SUM(b2.inwarded) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) /* current */ WHEN month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs - sales_left_to_do + Inward_expected_cogs /* future */ ELSE base_current_opening_cogs - ( SELECT SUM(b2.sales_left_to_do) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) + ( SELECT SUM(b2.Inward_expected_cogs) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) END ) * 30 / nullif(actual_sales + sales_left_to_do, 0),2) Closing_DOI, /* ================= CLOSING CALCULATED Target ================= */ round(greatest( 0,CASE /* past */ WHEN month_date < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs + ( SELECT SUM(b2.actual_sales) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) - ( SELECT SUM(b2.inwarded) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) /* current */ WHEN month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs - sales_left_to_do + COALESCE(INWARDED_TARGET_full_month-ifnull(inwarded,0), 0) /* future */ ELSE base_current_opening_cogs - ( SELECT SUM(b2.sales_left_to_do) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) + ( SELECT SUM(COALESCE(b2.INWARDED_TARGET_full_month-ifnull(b2.inwarded,0), 0)) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) END ),2) AS closing_target, round(greatest( 0,CASE /* past */ WHEN month_date < DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs + ( SELECT SUM(b2.actual_sales) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) - ( SELECT SUM(b2.inwarded) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') > calc.month_date AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) /* current */ WHEN month_date = DATE_TRUNC(\'MONTH\', CURRENT_DATE()) THEN base_current_opening_cogs - sales_left_to_do + COALESCE(INWARDED_TARGET_full_month-ifnull(inwarded,0), 0) /* future */ ELSE base_current_opening_cogs - ( SELECT SUM(b2.sales_left_to_do) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) + ( SELECT SUM(COALESCE(b2.INWARDED_TARGET_full_month-ifnull(b2.inwarded,0), 0)) FROM final_b b2 WHERE TO_DATE(b2.month_dt, \'YYYY-MM\') <= calc.month_date AND TO_DATE(b2.month_dt, \'YYYY-MM\') >= DATE_TRUNC(\'MONTH\', CURRENT_DATE()) AND b2.L1_Category = calc.L1_Category AND b2.category = calc.category ) END )* 30 / nullif(actual_sales + sales_left_to_do, 0),2) AS closing_doi_target, FROM calc left join (select L1_Category,category,avg(cogs) avg_cogs from sku_cogs group by 1,2) using (L1_Category,category) ORDER BY 1, 2, 3;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

